ders("AWL-16", "IELTS-AWL", "Academic Word List · Alt liste 5", 16, "Akademik kelimeler 16: değişim ve uyum",
 "IELTS ve YDS akademik kelime dizisi", "Değişim, uyum ve kapasite bildiren akademik kelimeler.",
 ["bf_emma", "am_michael"], "bm_lewis", [
 K("adjust", "uyum sağlamak, ayarlamak.", "It takes time to adjust to a new country.", "Yeni bir ülkeye uyum sağlamak zaman alır."),
 K("alter", "değiştirmek.", "The road has altered the landscape.", "Yol manzarayı değiştirdi."),
 K("amend", "değişiklik yapmak, düzeltmek.", "Parliament amended the law.", "Meclis yasada değişiklik yaptı."),
 K("capacity", "kapasite.", "The stadium has a capacity of fifty thousand.", "Stadyumun kapasitesi elli bin."),
 K("consult", "danışmak.", "You should consult a doctor.", "Bir doktora danışmalısın."),
 K("decline", "düşüş; azalmak; reddetmek.", "There has been a decline in sales.", "Satışlarda düşüş oldu."),
 K("enable", "olanak sağlamak.", "The new system enables faster payments.", "Yeni sistem daha hızlı ödemelere olanak sağlıyor."),
 K("external", "dış, harici.", "We hired an external consultant.", "Dışarıdan bir danışman tuttuk."),
 K("equivalent", "eşdeğer.", "Ten euros is roughly equivalent to eleven dollars.", "On avro aşağı yukarı on bir dolara eşdeğer."),
 K("evolve", "evrimleşmek, gelişmek.", "The company has evolved over the years.", "Şirket yıllar içinde gelişti."),
 K("expand", "genişlemek, büyümek.", "The business expanded into Asia.", "İşletme Asya'ya genişledi."),
 K("fundamental", "temel, köklü.", "There is a fundamental difference between them.", "Aralarında temel bir fark var."),
 ], [P("adjust to", "bir şeye uyum sağlamak."), P("a decline in", "bir şeyde düşüş."),
     P("expand into", "bir alana genişlemek."), P("a fundamental change", "köklü bir değişim.")],
 "Şimdi IELTS dinleme sınavının dördüncü bölümüne benzer kısa bir ders dinleyeceksiniz. Konu: kentler ve iklim değişikliği.",
 ["Cities around the world are having to adjust to a changing climate.",
  "As summers become hotter, many have begun to alter the way streets and buildings are designed.",
  "Some city councils have amended building rules so that new roofs must be green or white.",
  "Planners also consult external experts to measure the capacity of drains during heavy rain.",
  "In several European cities, there has been a decline in car use, and parks have expanded.",
  "New technology enables councils to monitor temperatures street by street.",
  "Experts argue that this is a fundamental change. City planning is evolving from a focus on cars to a focus on people and climate."],
 [Q("What rule have some city councils amended?", "Building rules, so that new roofs must be green or white."),
  Q("Why do planners consult external experts?", "To measure the capacity of drains during heavy rain."),
  Q("What has declined in several European cities?", "Car use.")],
 [bosluk("YDS köşesi", YDS_TALIMAT, ["The new law will", "small businesses to borrow money more easily."],
         ["enable", "decline", "consult", "amend", "adjust"], 0,
         ["T|Yeni yasa küçük işletmelerin daha kolay borç almasını sağlayacak.", "T|Olanak sağlamak anlamındaki fiil:", "E|enable."]),
  konusma("IELTS konuşma köşesi", IELTS3, "How will cities need to change in the future?",
          ["I think the most fundamental change will be a move away from private cars.",
           "Cities will need to expand public transport and create more green spaces, which also help to reduce heat.",
           "Buildings will have to adjust to hotter summers, for example with better insulation and green roofs.",
           "And technology will enable councils to plan much more precisely."])],
 dinleme_en=["Paris has changed a lot in recent years.", "The city has created hundreds of kilometres of new bike lanes,",
             "and some busy roads near the river have been closed to cars.",
             "Car traffic has fallen, and the number of people cycling has more than doubled.",
             "The city also plans to plant thousands of new trees to keep streets cooler in summer."],
 dinleme_en_sesi="bf_isabella"),

