ders("BA-16", "BA", "BABOK v3 kavramları · İş İngilizcesi", 16, "İş analizi 16: Uyum ve risk",
 "kıdemli iş analisti dizisi", "Mevzuata uyum, risk ve iç kontrol. Finans sektöründeki iş analistleri için temel kavramlar.",
 ["bf_emma", "bm_lewis"], "am_michael", [
 K("regulator", "düzenleyici kurum.", "The regulator fined the bank.", "Düzenleyici kurum bankaya ceza kesti."),
 K("know your customer", "müşterini tanı süreci.", "Know your customer checks are required for every new account.", "Her yeni hesap için müşteriyi tanıma kontrolleri gerekli."),
 K("anti-money laundering", "kara para aklamayı önleme.", "Anti-money laundering rules are very strict.", "Kara para aklamayı önleme kuralları çok katı."),
 K("data protection", "kişisel verilerin korunması.", "Data protection laws apply to all customer data.", "Kişisel verilerin korunması yasaları tüm müşteri verileri için geçerli."),
 K("data breach", "veri ihlali, veri sızıntısı.", "The data breach affected two million customers.", "Veri ihlali iki milyon müşteriyi etkiledi."),
 K("internal audit", "iç denetim.", "Internal audit reviewed the process.", "İç denetim süreci inceledi."),
 K("control", "kontrol, denetim mekanizması.", "We need a control to check every payment.", "Her ödemeyi kontrol eden bir mekanizma gerekiyor."),
 K("fraud detection", "dolandırıcılık tespiti.", "The fraud detection system blocked the payment.", "Dolandırıcılık tespit sistemi ödemeyi durdurdu."),
 K("risk appetite", "risk iştahı, kabul edilebilir risk düzeyi.", "Our risk appetite is low.", "Risk iştahımız düşük."),
 K("segregation of duties", "görevler ayrılığı.", "Segregation of duties means one person can't approve their own payment.", "Görevler ayrılığı, kimsenin kendi ödemesini onaylayamaması demek."),
 K("regulatory reporting", "yasal raporlama.", "Regulatory reporting is due every month.", "Yasal raporlama her ay yapılmalı."),
 K("audit finding", "denetim bulgusu.", "We must close the audit finding by June.", "Denetim bulgusunu hazirana kadar kapatmalıyız."),
 ], [P("Is this compliant?", "Bu mevzuata uygun mu?"), P("What's the risk if we don't?", "Yapmazsak risk ne?"),
     P("Who approves it?", "Kim onaylıyor?"), P("We need an audit trail.", "Bir denetim izi gerekiyor.")],
 "Şimdi iş analistinin uyum birimi yöneticisiyle yaptığı, bir denetim bulgusu üzerine toplantıyı dinleyeceksiniz.",
 ["CO|Internal audit has raised an audit finding about our new online account process.", "BA|What exactly did they find?",
  "CO|The know your customer checks are done after the account is opened, not before. That's against anti-money laundering rules.",
  "BA|So we need a control that blocks the account until the checks are complete. Who approves exceptions today?",
  "CO|The same person who creates the account. That's a problem for segregation of duties.",
  "BA|Then I'll add a requirement for a second approver. What's our risk appetite here?",
  "CO|Very low. If the regulator finds it, we could face a fine.",
  "BA|Understood. And customer documents contain personal data, so data protection rules apply. Where are they stored?",
  "CO|In a shared folder. After last year's data breach at another bank, we can't accept that.",
  "BA|I'll include secure storage, a full audit trail, and a link to the fraud detection system. Do we also need changes to regulatory reporting?",
  "CO|Yes, the monthly report must show how many accounts were blocked."],
 [Q("What did internal audit find?", "The know your customer checks are done after the account is opened."),
  Q("Why is the current approval a problem?", "The same person creates the account and approves exceptions."),
  Q("Where are customer documents stored now?", "In a shared folder.")],
 [konusma("Toplantı simülasyonu", ["Şimdi bir toplantı simülasyonu. Bir ürün yöneticisi, uyum kontrollerini atlayarak yeni ürünü hızla çıkarmak istiyor.",
                                   "Riski açıklayıp kibarca bir çözüm önerin. On beş saniyeniz var."],
          "Can we skip the compliance checks for now and add them later?",
          ["I understand we're under time pressure.", "But if the regulator finds missing checks, we could face a fine and lose customer trust.",
           "Could we launch with a smaller group of customers, with all the controls in place?"], 15),
  konusma("Mülakat köşesi", MULAKAT, "How do you handle regulatory requirements in a project?",
          ["I involve the compliance and risk teams from the very beginning, not at the end.",
           "I translate each regulation into clear, testable requirements, and I link every requirement to its source.",
           "I check that the design includes the right controls, such as segregation of duties and an audit trail.",
           "Finally, I make sure the test plan covers these controls, so that we can show evidence to internal audit and the regulator."])],
 konusmacilar={"BA": "bf_emma", "CO": "bm_lewis"},
 dinleme_en=["Europe's data protection law, known as GDPR, came into force in 2018.",
             "It gives people the right to see the data that companies hold about them, and to ask for it to be deleted.",
             "Companies must report a serious data breach within seventy-two hours.",
             "Fines can reach four percent of a company's global income, so firms now take data protection very seriously."],
 dinleme_en_sesi="af_heart"),

